// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.sttimport com.roshan.persona.voice.capture.AudioCapturePipeline/** * NOUS — STT Confidence Scorer (v2 review 2 upgrade, §22). * * Cloud STT engines return a confidence score directly. Offline engines * (Whisper.cpp, Vosk) don't always — when they don't, this class estimates * confidence from audio quality signals (SNR, voice activity ratio, audio * energy stability) so the Brain can make the same trust decisions it makes * for cloud results. * * ## Brain trust levels (§22) * * ``` * confidence > 0.85 → HIGH *     - Process normally *     - Critical commands (call, delete, send) execute immediately * * confidence 0.60 – 0.85 → MEDIUM *     - Process normally *     - Critical intents trigger "Did you mean...?" confirmation * * confidence < 0.60 → LOW *     - Don't execute anything *     - TTS speaks: "I couldn't quite hear you. Could you repeat that?" * ``` * * ## Why estimate confidence for offline STT? * * The Brain's behavior changes dramatically with confidence — at LOW it * should not execute critical commands even if the intent classifier * returned a high-intent-confidence score (because the *text* itself might * be wrong). Without a confidence score, offline STT would either always * trigger the "repeat that" path (annoying) or never (unsafe). This class * gives offline STT a reasonable middle ground. * * ## Testability * * [scoreFromAudio] is a pure function of the audio chunk + a baseline * energy threshold — easy to unit-test. [classify] is a pure function of * the score + thresholds. The combined [scoreAndClassify] is what the * StreamingSttEngine calls. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§22 STT Confidence Scoring</a> */class SttConfidenceScorer(    private val thresholds: ConfidenceThresholds = ConfidenceThresholds(),) {    /**     * Classify a confidence score into a [TrustLevel] that the Brain uses     * to decide between normal processing, confirmation, or "repeat that".     */    fun classify(confidence: Float): TrustLevel = when {        confidence >= thresholds.high -> TrustLevel.HIGH        confidence >= thresholds.medium -> TrustLevel.MEDIUM        else -> TrustLevel.LOW    }    /**     * Estimate confidence for an offline STT result that didn't provide one.     *     * Heuristic — combines three signals:     *  1. **Voice activity ratio** — what fraction of the utterance had     *     detectable voice? Low ratio → noisy room → low confidence.     *  2. **Energy stability** — how stable was the speech energy? Large     *     swings → user moving around / wind → low confidence.     *  3. **Peak-to-RMS ratio** — clipped audio (shouting into mic) has a     *     low ratio → distortion → low confidence.     *     * Returns a value in [0, 1]. Real implementations should use a small     * ML model trained on (audio_features, true_confidence) pairs from     * cloud STT — this heuristic is the v1 fallback.     */    fun scoreFromAudio(chunks: List<AudioCapturePipeline.AudioChunk>): Float {        if (chunks.isEmpty()) return 0f        // 1. Voice activity ratio.        val voiceChunks = chunks.count { it.hasVoice }        val voiceRatio = voiceChunks.toFloat() / chunks.size        // 2. Energy stability (coefficient of variation of per-chunk RMS).        val rmsValues = chunks.map { rms(it.samples) }        val meanRms = rmsValues.average().toFloat()        val stdRms = if (rmsValues.size > 1) {            kotlin.math.sqrt(                rmsValues.sumOf { (it - meanRms).toDouble() * (it - meanRms).toDouble() } / rmsValues.size            ).toFloat()        } else 0f        val cov = if (meanRms > 0) (stdRms / meanRms) else 1f        val stabilityScore = (1f - cov).coerceIn(0f, 1f)        // 3. Peak-to-RMS ratio on the last few chunks (most recent speech).        val recent = chunks.takeLast(minOf(10, chunks.size))        val allSamples = recent.flatMap { it.samples.toList() }        if (allSamples.isEmpty()) return 0f        val peak = allSamples.maxOf { kotlin.math.abs(it.toInt()) }.toFloat()        val overallRms = kotlin.math.sqrt(            allSamples.sumOf { it.toLong() * it.toLong() }.toDouble() / allSamples.size        ).toFloat()        // Healthy speech: peak/RMS ~4-8 (10-18 dB crest factor).        // Clipped (shouting): peak/RMS ~2-3 (low crest factor → distorted).        // Silence + noise: peak/RMS very high (peak dominated by transient).        val prr = if (overallRms > 0) peak / overallRms else 0f        val prrScore = when {            prr in 4f..12f -> 1f                  // healthy            prr in 2f..4f -> 0.6f                 // possibly clipped            prr > 12f -> 0.5f                     // transient-dominated (wind/keyboarding)            else -> 0.3f                          // too low or all-zero        }        // Weighted combination. Voice ratio is the dominant signal because        // the Brain's "ask to repeat" behavior is mostly triggered by        // noisy-room scenarios where STT is transcribing garbage.        val combined = 0.5f * voiceRatio +            0.25f * stabilityScore +            0.25f * prrScore        return combined.coerceIn(0f, 1f)    }    /**     * Combined helper: estimate confidence for an offline result and classify     * it in one call. Convenience for the [OfflineSttEngine] implementations.     */    fun scoreAndClassify(chunks: List<AudioCapturePipeline.AudioChunk>): Pair<Float, TrustLevel> {        val score = scoreFromAudio(chunks)        return score to classify(score)    }    /** Compute RMS (root-mean-square) of a PCM chunk. */    private fun rms(samples: ShortArray): Float {        if (samples.isEmpty()) return 0f        var sumSq = 0L        for (s in samples) sumSq += s.toInt().toLong() * s.toInt().toLong()        return kotlin.math.sqrt(sumSq.toDouble() / samples.size).toFloat()    }}// ──────────────────────────────────────────────────────────────────────────/** * Tunable thresholds for [SttConfidenceScorer.classify]. * * Defaults match the v2 strategy doc §22: *  - HIGH:   > 0.85 *  - MEDIUM: 0.60 – 0.85 *  - LOW:    < 0.60 */data class ConfidenceThresholds(    val high: Float = 0.85f,    val medium: Float = 0.60f,) {    init {        require(high in 0f..1f) { "high threshold must be in [0,1], got $high" }        require(medium in 0f..1f) { "medium threshold must be in [0,1], got $medium" }        require(medium <= high) { "medium ($medium) must be <= high ($high)" }    }}// ──────────────────────────────────────────────────────────────────────────/** * Trust level the Brain uses to decide how to handle an STT result. * * Mapping to Brain behavior (§22): *  - HIGH   → process normally; critical commands execute immediately. *  - MEDIUM → process normally; critical intents trigger "Did you mean...?". *  - LOW    → don't execute; TTS speaks "I couldn't quite hear you...". * * Wired into the Brain in Step 5.14 (VoiceModule Hilt wiring). */enum class TrustLevel {    HIGH,    MEDIUM,    LOW,}